    "sourceHash": "sha256:a09fd1ea1bf080aae3bf15df129c9d2956b4fcd1f482cd976301ce26dcafb92d",
    "translatableHash": "sha256:0588dfb7fbb401e0b7fc6ec541c2f887722d0f74bd94f2e726f0cdd94134edf7",
    "data": {
      "schemaVersion": 1,
      "name": "Ordulf Bladecaller",
      "level": 16,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "human",
        "humanoid"
      ],
      "description": "",
      "armorClass": 38,
      "hitPoints": 300,
      "speedFeet": 25,
      "perception": {
        "modifier": 28,
        "senses": []
      },
      "saves": {
        "fortitude": 30,
        "reflex": 25,
        "will": 28
      },
      "abilities": {
        "str": 5,
        "dex": 1,
        "con": 4,
        "int": 0,
        "wis": 4,
        "cha": 5
      },
      "skills": {
        "acrobatics": 25,
        "athletics": 29,
        "crafting": 24,
        "intimidation": 31,
        "religion": 28,
        "survival": 28
      },
      "languages": [
        "common",
        "jotun",
        "skald"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [
          "cold 10"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "gLrDw8hqWk2avRSb",
          "name": "Greatsword",
          "bonus": 32,
          "damage": "3d12+11 slashing; 1d6 cold",
          "traits": [
            "magical",
            "versatile-p"
          ]
        },
        {
          "id": "xq78LjtEELYdQTVj",
          "name": "Greataxe",
          "bonus": 32,
          "damage": "3d12+11 slashing; 1d6 bleed",
          "traits": [
            "magical",
            "sweep"
          ]
        }
      ],
      "actions": [
        {
          "id": "RPk0bywqzPIIzv9B",
          "name": "Battle Arrogance",
          "kind": "passive",
          "description": "Ordulf hasn't met a significant combat challenge in ages, and even when facing deadly foes like the PCs his arrogance can be used against him. If a PC successfully Disarms, Feints, Frightens, or Trips Ordulf, his arrogance gets the better of him and he grows sloppy in his tactics, reducing his AC to 34 until the start of his next turn. A PC can also attempt to issue a more debilitating insult to Ordulf.\nInsult Ordulf 2\nThe PC spends several seconds issuing insults and taunts to Ordulf, then attempts a check (deception, dc:38), check (intimidation, dc:38), or check (performance, dc:38) check. If the insults include challenges to Ordulf's bravery, compare him to a troll or a chicken, insult his skill at fishing, or liken him to a witch or national of Irrisen, this becomes a DC 33 check.\nCritical Success You strike a nerve. Not only does Ordulf become Sickened 2 with anger, he is also Stunned 1 from the shock of your words.\nSuccess Your insults cause Ordulf to become sickened 2 with anger.\nFailure Your insult only has a brief effect, causing Ordulf to become Sickened 1. He automatically recovers from this sickened condition at the end of his next turn.\nCritical Failure Your attempt to insult Ordulf fails so spectacularly that he becomes temporarily immune to Insult Ordulf activities from you for 24 hours.",
          "traits": []
        },
        {
          "id": "BhfPRzd1V4WjeoTQ",
          "name": "Gorum's Major Boon",
          "kind": "passive",
          "description": "When Ordulf is reduced to 0 Hit Points, Gorum feeds him the zeal of his Aesir, allowing Ordulf to draw upon his own life force to fight on and on without falling. He is healed to 150 Hit Points and becomes Doomed 1 (or increases his doomed condition by 1), causing his features to look progressively more gaunt and scarred. Once he reaches Doomed 4, he dies.",
          "traits": [
            "healing"
          ]
        },
        {
          "id": "L0apVhPMH7U617wJ",
          "name": "Reactive Strike",
          "kind": "reaction",
          "description": "",
          "traits": []
        },
        {
          "id": "vbzf1jM9Z6h4aA4v",
          "name": "Battle Cry",
          "kind": "reaction",
          "description": "Frequency once per day\nTrigger Ordulf rolls initiative\nEffect Ordulf attempts to Demoralize an observed foe.",
          "traits": []
        },
        {
          "id": "GAMpBm8xt4OWSN3g",
          "name": "Cleaving Blow",
          "kind": "action",
          "description": "Ordulf Strikes two adjacent creatures within his reach. Both attacks count against his multiple attack penalty, but do not increase his penalty until he has made both attacks.",
          "traits": []
        },
        {
          "id": "0zqThhDwY1ahBi56",
          "name": "Crushing Insult",
          "kind": "action",
          "description": "Frequency once per round\nEffect Ordulf issues a devastating and humiliating insult to a creature within 30 feet that he can see. Ordulf attempts an check (intimidation, defense:will) check against the target's Will DC. That character is then temporarily immune to Crushing Insult for 24 hours.\nCritical Success The insult is distracting and humiliating; the target is Stupefied 1 and Off-Guard for 1 minute.\nSuccess The insult is distracting, but its effects pass quickly; the target is stupefied 1 and off-guard until the start of Ordulf's next turn.\nFailure The insult barely cuts, but is distracting enough that the target is off-guard until the end of Ordulf's turn.\nCritical Failure Ordulf's attempted insult fails spectacularly, and the PC who he was attempting to insult can instantly insult him back, using Insult Ordulf as a free action.",
          "traits": [
            "auditory",
            "linguistic",
            "mental"
          ]
        },
        {
          "id": "yb7EXfXGwEOjyuMz",
          "name": "Deadly Display",
          "kind": "action",
          "description": "Requirements Ordulf is wielding a melee weapon\nEffect Ordulf brandishes his weapon in a threatening display. He Demoralize all enemies within 30 feet, rolling once and comparing the result to each target's Will DC.",
          "traits": []
        },
        {
          "id": "uoGFxPXwtRh6lZCO",
          "name": "Whirlwind Strike",
          "kind": "action",
          "description": "Ordulf Strikes each enemy within his reach. Each attack counts toward his multiple attack penalty, but do not increase his penalty until he has made all his attacks.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
