      "actions": [
        {
          "id": "oty1fVL7nytTRKpZ",
          "name": "Molten Spray",
          "kind": "reaction",
          "description": "Trigger Temperbrand takes physical damage\nEffect Temperbrand's body erupts at the site of the damage to spray molten iron into an adjacent square of her choice. Any creature occupying that square takes 9d6 fire damage (check (reflex, dc:37, basic) save).",
          "traits": [
            "fire",
            "primal"
          ]
        },
        {
          "id": "91tswEjWQhqYcQMg",
          "name": "Vulnerable to Water",
          "kind": "passive",
          "description": "Whenever Temperbrand is targeted with a water effect, she takes 6d6 cold damage and becomes Slowed 1 for 1d4 as her body hardens into solid metal. As long as she remains slowed, her Armor Class increase to 43.",
          "traits": []
        },
        {
          "id": "VmbUFfyz2JFBZda2",
          "name": "Hurl Slagblade",
          "kind": "action",
          "description": "Temperbrand whips an arm at a target within 120 feet, causing her slagblade to detach and fly through the air. The target creature must attempt a check (reflex, dc:40, options:damaging-effect) save. Temperbrand regrows a new slagblade instantly but can't use Hurl Slag again for 1d4.\nCritical Success The creature is unaffected.\nSuccess The creature takes 5d10 fire damage.\nFailure The creature takes 10d10 fire damage, and the slag hardens, causing the creature to become Slowed 1 for 3 rounds. A creature can end the slowed condition early by Escaping (DC 40) the confining slag.\nCritical Failure The creature takes 20d10 fire damage, and the slag swiftly anchors them in place, causing the creature to become Restrained until they Escape DC 40.",
          "traits": [
            "divine",
            "fire",
            "incapacitation",
            "primal"
          ]
        },
        {
          "id": "5Z7ExxF7eeMMWGNg",
          "name": "Ooze Form",
          "kind": "action",
          "description": "Temperbrand's body becomes amorphous. Her AC becomes 30, and she becomes immune to critical hits and precision damage. While in this form she is blind (but retains her tremorsense), and her Speeds are reduced by 15 feet (to a minimum of 5 feet). She can move through spaces as if she were a Tiny creature without penalty. As long as she remains in Ooze Form, she can't make slagblade Strikes or Hurl Slagblade, but she gains Trample. She can end Ooze Form by using this action again.",
          "traits": [
            "concentrate",
            "polymorph",
            "primal"
          ]
        },
        {
          "id": "e0tjsf7T1loknJPQ",
          "name": "Slagblade Storm",
          "kind": "action",
          "description": "Temperbrand Strikes all creatures within her reach with a slagblade Strike. Her multiple attack penalty doesn't increase until the end of this activity.",
          "traits": []
        },
        {
          "id": "wgBkMsNWhjY1680F",
          "name": "Trample (Ooze Form Only)",
          "kind": "action",
          "description": "Large or smaller, Foot, check (reflex, dc:40, basic)",
          "traits": []
        }
      ],
      "spellcasting": []
