    "sourceHash": "sha256:bcc3a28c7836d7d09fa9a5d144bf09d4ba06e33798eee7653c2f226be63e4481",
    "translatableHash": "sha256:1b80f7b7dfbfecee680fd1ad0a1ce8982d9890c409be293603522630d0299b11",
    "data": {
      "schemaVersion": 1,
      "name": "Silver Saber",
      "level": 18,
      "rarity": "unique",
      "size": "huge",
      "traits": [
        "construct"
      ],
      "description": "This construct was built hundreds of years ago by Red Mantis arcanists, then imbued with intelligence as a divine protector by priests of Achaekek not long after the assassin cult fled Rahadoum. Silver Saber's single purpose is to guard the secrets of the Blood Mistress from those who are unworthy.\nWhen at rest, Silver Saber appears as an ornate mirror, but when confronted in battle they animate into the form of a praying mantis made of polished, almost liquid silver with a blank humanoid face.\nLife as a Mirror\nSilver Saber has watched the followers of Achaekek for centuries, sitting silently in their gold frame and pretending to be a mirror. They know more about the secret lives of the Red Mantis than has ever been recorded in the Sarzari, but their objective isn't to record history, it's to function as a guardian—no more, no less.",
      "armorClass": 43,
      "hitPoints": 260,
      "speedFeet": 40,
      "perception": {
        "modifier": 32,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 30,
        "reflex": 33,
        "will": 28
      },
      "abilities": {
        "str": 8,
        "dex": 7,
        "con": 6,
        "int": 3,
        "wis": 6,
        "cha": 5
      },
      "skills": {
        "acrobatics": 33,
        "athletics": 34,
        "deception": 33,
        "society": 31
      },
      "languages": [
        "common",
        "diabolic",
        "osiriani"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [
          "physical 15 except adamantine"
        ],
        "weaknesses": [
          "cold 15"
        ]
      },
      "attacks": [
        {
          "id": "c4ZDd6QzElgipauV",
          "name": "Leg",
          "bonus": 33,
          "damage": "3d10+16 slashing; 2d6 bleed",
          "traits": [
            "magical",
            "reach-10"
          ]
        },
        {
          "id": "X9nA0pl2JxP44f78",
          "name": "Spike",
          "bonus": 33,
          "damage": "3d6+16 piercing",
          "traits": [
            "magical"
          ]
        }
      ],
      "actions": [
        {
          "id": "najvbpZ4hTXixuHn",
          "name": "Evasion",
          "kind": "passive",
          "description": "When Silver Saber rolls a success on a Reflex save, they get a critical success instead.",
          "traits": []
        },
        {
          "id": "SWuWOBMne2JdbaYS",
          "name": "Faith Bound",
          "kind": "passive",
          "description": "Silver Saber can't attack a creature that openly wears or displays Achaekek's religious symbol unless that creature uses a hostile action against Silver Saber first. They can also attack a creature they believe isn't faithful to Achaekek or who wears the religious symbol as a ruse (typically after succeeding at a Perception check to Sense Motive).",
          "traits": [
            "divine"
          ]
        },
        {
          "id": "nZEzSnl1osNRoGGn",
          "name": "Reflect Truths",
          "kind": "passive",
          "description": "20 feet. A creature that enters the area must succeed at a check (will, dc:37) save or they see their own visage in Silver Saber's reflective face looking back at them. For 1 minute, that creature can't speak any deliberate and intentional lies and takes a –2 status penalty to Deception checks. On a critical failure, the status penalty is increased to –4.",
          "traits": [
            "aura",
            "divine",
            "mental",
            "visual"
          ]
        },
        {
          "id": "wnfmu5GVCsHatUbm",
          "name": "Focus Gaze",
          "kind": "action",
          "description": "Silver Saber focuses their gaze on a creature they can see within 30 feet. The target must immediately attempt a Will save against Reflect Truths. If the creature was already so affected, it becomes Stunned 1. After attempting its save, the creature is then temporarily immune until the start of Silver Saber's next turn.",
          "traits": [
            "aura",
            "divine",
            "incapacitation",
            "mental",
            "visual"
          ]
        },
        {
          "id": "eC4JAtK9eWRwAZcj",
          "name": "Liquefy",
          "kind": "action",
          "description": "Silver Saber becomes fully liquid and amorphous. They gain immunity to precision damage but take double cold damage. The only actions they can use while liquefied are move actions and spike ranged Strikes. They can resume their normal form by taking this action again.",
          "traits": []
        },
        {
          "id": "ooTa76om3tYNYUSd",
          "name": "Mirror",
          "kind": "action",
          "description": "Until the next time they act, Silver Saber appears to be a mirror. They have an automatic result of 53 on Deception checks and DCs to pass as a mirror.",
          "traits": [
            "concentrate"
          ]
        },
        {
          "id": "yQ96bFm5BMr0cThy",
          "name": "Silver Strikes",
          "kind": "passive",
          "description": "Silver Saber's leg and spike Strikes count as silver weapons.",
          "traits": []
        },
        {
          "id": "T5opMomQIIGaeZAL",
          "name": "Swift Steps",
          "kind": "passive",
          "description": "Silver Saber is permanently Quickened, but they can use the extra action only to Step or Stride.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
