    "sourceHash": "sha256:0291908ea46fab675f6d26b207d1a4fe4ee8ec48ba28e7e254545feb8ea42a66",
    "translatableHash": "sha256:4578af39dd169fc9dd7a133cd19a79e469cb7b06122d746b506c4cb00e2b7e5d",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Grove of Despair",
      "level": 3,
      "rarity": "uncommon",
      "size": "large",
      "traits": [
        "haunt"
      ],
      "description": "An eerie fog fills a lonely stretch of forest.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 12,
        "details": "(trained)"
      },
      "disable": "check (diplomacy, dc:22) (untrained) to Request that the spirits leave or check (religion, dc:20) (trained) to exorcise the spirits. All creatures and objects within the fog are Concealed, and all creatures and objects outside the fog are concealed to creatures within it.",
      "isComplex": true,
      "routine": "(1 action; auditory, emotion, fear, mental) The haunt attempts an Intimidation check with a 1d20+12 modifier against the Will DC of each Frightened creature as it fills their minds with haunting whispers.\nCritical Success The creature takes 4d6 mental damage and its frightened condition increases by 1, to a maximum of Frightened 3.\nSuccess The creature takes 2d6 mental damage.\nFailure The creature is unaffected.\nCritical Failure The creature's frightened condition is reduced by 1.",
      "reset": "The haunt falls silent for 24 hours once all frightened creatures die or reduce their frightened condition's value to 0. During this time, a creature that isn't frightened can exorcise the spirits with a check (religion, dc:20) check, permanently destroying the haunt.",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "0lDGihFsmPnhHNN1",
          "name": "Despairing Whispers",
          "kind": "reaction",
          "description": "Trigger A living creature enters the haunted area\nEffect The spirits manifest, whispering in the minds of creatures in the fog. Each creature in the area must succeed at a check (will, dc:22) save or be Frightened 1 (Frightened 2 on a critical failure). Frightened creatures are Immobilized for as long as they remain frightened. The haunt then rolls initiative.",
          "traits": [
            "auditory",
            "emotion",
            "fear",
            "mental"
          ]
        }
      ]
    },
