    "data": {
      "schemaVersion": 1,
      "name": "Crawling Hand (BB)",
      "level": -1,
      "rarity": "common",
      "size": "tiny",
      "traits": [
        "undead",
        "unholy"
      ],
      "description": "Crawling hands form when severed appendages are endowed with a crude sentience by necromantic energies that turn them into tireless killers.",
      "armorClass": 12,
      "hitPoints": 8,
      "speedFeet": 30,
      "perception": {
        "modifier": 5,
        "senses": [
          "lifesense-30"
        ]
      },
      "saves": {
        "fortitude": 2,
        "reflex": 5,
        "will": 2
      },
      "abilities": {
        "str": 1,
        "dex": 3,
        "con": 0,
        "int": -4,
        "wis": 0,
        "cha": 0
      },
      "skills": {
        "athletics": 5,
        "stealth": 6,
        "survival": 2
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "bleed",
          "mental",
          "poison",
          "unconscious",
          "void",
          "visual"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "HvL4pznzaaZwsFkA",
          "name": "Claw",
          "bonus": 7,
          "damage": "1d4+1 slashing",
          "traits": [
            "agile",
            "finesse",
            "reach-0",
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "twuwqjXSZmaqi54S",
          "name": "Lifesense",
          "kind": "passive",
          "description": "A crawling hand can sense the vital essence of living and undead creatures within 30 feet. This sense can distinguish between the vitality energy animating living creatures and the void energy animating undead creatures, much as sight distinguishes color. However, a crawling hand can't see, so effects that depend on vision or seeing don't work on it.",
          "traits": []
        },
        {
          "id": "iThujq9Fhag6Jad2",
          "name": "Throat Grab",
          "kind": "action",
          "description": "When the crawling hand succeeds at its claw Strike against a Medium or smaller creature, it can use this action immediately after to attempt to Grapple the target. This Grapple doesn't apply or count toward the crawling hand's multiple attack penalty. A creature Grabbed this way has difficulty speaking and must spend an extra action to perform any action that requires speaking, including casting spells.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
