    "translatableHash": "sha256:a4ce82826bf2f107c2e4ef8db55bbcd8b485e541c55c5c6b16dc56c7b4c8614a",
    "data": {
      "schemaVersion": 1,
      "name": "Magnetic Skink",
      "level": 0,
      "rarity": "common",
      "size": "small",
      "traits": [
        "animal"
      ],
      "description": "The scales of these large lizards are magnetic, drawing scraps of metal to their bodies. In addition to eating insects and other small prey, magnetic skinks also feed on small amounts of metal, so they're known to reside near settlements with access to these materials.",
      "armorClass": 15,
      "hitPoints": 10,
      "speedFeet": 30,
      "perception": {
        "modifier": 8,
        "senses": [
          "low-light-vision"
        ]
      },
      "saves": {
        "fortitude": 8,
        "reflex": 5,
        "will": 2
      },
      "abilities": {
        "str": 2,
        "dex": 3,
        "con": 4,
        "int": -4,
        "wis": 2,
        "cha": -1
      },
      "skills": {
        "acrobatics": 4,
        "athletics": 4,
        "stealth": 4
      },
      "languages": [],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "E9NtlIKF3oVafAVk",
          "name": "Jaws",
          "bonus": 5,
          "damage": "1d6 piercing",
          "traits": []
        }
      ],
      "actions": [
        {
          "id": "Ug3XiChjdFdUphbA",
          "name": "Uncanny Climber",
          "kind": "passive",
          "description": "A magnetic skink's feet allow it to climb virtually any surface, no matter how slick or sheer. If a skink attempts an Athletics check to Climb and critically fails, it gets a failure instead.",
          "traits": []
        },
        {
          "id": "5hBW5iuHtYk2UaGh",
          "name": "Launch Metal",
          "kind": "action",
          "description": "The skink repulses the metal attached to its body in all directions, dealing 2d6 bludgeoning damage (check (reflex, dc:15, basic, options:area-effect) save) to all creatures adjacent to the skink. The skink can't use Launch Metal again for 1d4.",
          "traits": []
        },
        {
          "id": "lDeS18dnskh4FIBw",
          "name": "Unsteadying Magnetism",
          "kind": "action",
          "description": "The skink amplifies its magnetic field and tries to pull the metal away from a creature within 20 feet. If that creature is wearing metal armor or holding a metal item, they must attempt a check (fortitude, dc:15) save. On a failure, that creature is Off-Guard until the start of the skink's next turn.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
