    "data": {
      "schemaVersion": 1,
      "name": "Ferrous Butterfly (BB)",
      "level": 1,
      "rarity": "common",
      "size": "tiny",
      "traits": [
        "elemental",
        "metal"
      ],
      "description": "Beautiful but deadly, the ferrous butterfly is a turkey-sized insectile creature bristling with dozens of gleaming, razor-edged blades. Considered harmless by most denizens of the Plane of Metal, they nonetheless pose a significant threat to organic creatures, whose iron-rich blood they find irresistible. The wing blades of these butterflies tend to break off during feeding and regrow naturally. These scales are reminiscent of jagged scraps of metal and can serve as surprisingly effective makeshift weapon.",
      "armorClass": 15,
      "hitPoints": 20,
      "speedFeet": 5,
      "perception": {
        "modifier": 7,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 6,
        "reflex": 9,
        "will": 5
      },
      "abilities": {
        "str": 2,
        "dex": 4,
        "con": 3,
        "int": -4,
        "wis": 0,
        "cha": 0
      },
      "skills": {
        "acrobatics": 9
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "bleed",
          "poison",
          "sleep"
        ],
        "resistances": [
          "electricity 3"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "HbXWwzIGe9qlYvrg",
          "name": "Wing",
          "bonus": 9,
          "damage": "1 bleed; 1d4+2 slashing",
          "traits": [
            "finesse"
          ]
        }
      ],
      "actions": [
        {
          "id": "rRGMTgMxN0CtANkU",
          "name": "A Thousand Cuts",
          "kind": "passive",
          "description": "A ferrous butterfly's knifelike wings cause terrible lacerations that continue to bleed. Any creature with persistent bleed damage from a ferrous butterfly's wing attack has weakness 2 to slashing damage until the bleeding is stopped.\nEffect: A Thousand Cuts",
          "traits": []
        },
        {
          "id": "RIciu5HI9XP7Ecbs",
          "name": "Swoop",
          "kind": "action",
          "description": "The ferrous butterfly Flies up to its Speed and makes a wing Strike at any point during that movement.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
