    "translatableHash": "sha256:d314e19594d6b434cd33b511e2986c9bb15bcaa03ae849fb88e86232a689c73d",
    "data": {
      "schemaVersion": 1,
      "name": "Giant Fly (BB)",
      "level": 1,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "animal"
      ],
      "description": "This massive fly's twitching limbs seem to never stop moving as it constantly cleans itself and scoops anything edible into its mouth parts. While primarily carrion eaters, giant flies sometimes prey on livestock or other animals too slow to get away. Left to their own devices, these flies will lay dozens of eggs within the mostly-eaten carcasses. These eggs soon hatch into enormous maggots that begin the cycle of scavenging anew.",
      "armorClass": 16,
      "hitPoints": 20,
      "speedFeet": 20,
      "perception": {
        "modifier": 8,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 6,
        "reflex": 9,
        "will": 6
      },
      "abilities": {
        "str": 3,
        "dex": 4,
        "con": 3,
        "int": -5,
        "wis": 3,
        "cha": -5
      },
      "skills": {
        "acrobatics": 7,
        "athletics": 6
      },
      "languages": [],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "6dTWfzgW656sz0hE",
          "name": "Mandibles",
          "bonus": 8,
          "damage": "1d6+3 piercing",
          "traits": []
        }
      ],
      "actions": [
        {
          "id": "cWmhZcEZc9lfN3YX",
          "name": "Avoid the Swat",
          "kind": "reaction",
          "description": "Trigger The giant fly is targeted with a melee or ranged attack by an attacker it can see\nEffect The giant fly gains a +2 circumstance bonus to AC against the triggering attack. If the attack misses, the giant insect can Fly up to its fly Speed.",
          "traits": []
        },
        {
          "id": "cVC4VEACXb51B5a4",
          "name": "Fly Pox",
          "kind": "passive",
          "description": "A giant fly could carry any disease, but most transmit an infection called fly pox with their bite. A character who is critically hit by a giant fly's mandibles must succeed at a check (fortitude, dc:16, options:inflicts:enfeebled) saving throw or be Enfeebled 1 for 1 day.",
          "traits": [
            "disease"
          ]
        }
      ],
      "spellcasting": []
    },
