    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Poisonous Atmosphere",
      "level": 1,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "environmental",
        "magical",
        "mental",
        "poison"
      ],
      "description": "Aucturn's poisonous, magical atmosphere has strange effects on the planet's creatures.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 5,
        "details": "(expert) to identify the source of sudden nausea"
      },
      "disable": "check (survival, dc:20) (trained) or check (occultism, dc:20) (trained) to breathe pockets of safe air trapped in bags and clothing",
      "isComplex": true,
      "routine": "(1 action; illusion, mental, occult) The atmosphere continues to affect all creatures in the area, requiring a new Fortitude save each round against its Poisonous Atmosphere. A creature holding its breath gains a +2 circumstance bonus to the save.",
      "reset": "",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "81TM77XkpxMHX0Aa",
          "name": "Poisonous Atmosphere",
          "kind": "reaction",
          "description": "Trigger A non-native creature breathes the atmosphere\nEffect The triggering creature must attempt a check (fortitude, dc:17) save. The hazard then rolls initiative.\nCritical Success The creature is invigorated by the atmosphere and is Quickened for 1 round.\nSuccess The creature is unaffected.\nFailure The creature is Clumsy 1.\nCritical Failure The creature is Confused for 1 round.",
          "traits": [
            "illusion",
            "mental",
            "occult"
          ]
        }
      ]
    },
