    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Cordon Alarm",
      "level": 2,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "A hempen rope tied between trees emanates an invisible, cylindrical barrier that sounds an alarm when crossed.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 8,
        "details": "(trained)"
      },
      "disable": "check (thievery, dc:18) (trained) to move the rope without setting of the alarm, or Dispel Magic (1st rank; counteract DC 16) to disable the rope's magic",
      "isComplex": false,
      "routine": "",
      "reset": "The alarm resets immediately. Multiple breaches can cause the alarm to sound in multiple places at the same time, though the alarm can still be triggered only once per round.",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "jaO67z3pJGTF07wI",
          "name": "Alarm",
          "kind": "reaction",
          "description": "Trigger An object or creature of at least 1 Bulk crosses an invisible vertical barrier extending 30 feet above and below the rope\nEffect The rope squawks like an angry squirrel from the point where the barrier was breached. This alarm is as loud as a human scream and lasts for 1 minute. If an item or creature is still breaching the barrier at the end of this duration, the alarm immediately triggers again.",
          "traits": [
            "primal"
          ]
        }
      ]
    },
