    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Corpse Disposal",
      "level": 2,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "mechanical",
        "trap"
      ],
      "description": "A wooden trapdoor conceals a spike-filled pit 10 feet square and 20 feet deep. The DC to Climb out of the pit is check (athletics, dc:10, traits:action:climb).",
      "armorClass": 18,
      "hitPoints": 30,
      "hardness": 9,
      "stealth": {
        "modifier": 11,
        "details": "(or 0 if the trapdoor is disabled or broken)"
      },
      "disable": "check (thievery, dc:18) (trained) to jam the trapdoor open",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 7,
        "reflex": 7,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "AzjAwOYPy29W8Oku",
          "name": "Dispose",
          "kind": "reaction",
          "description": "Trigger A creature steps onto the trapdoor (marked \"T\" on the map)\nEffect The triggering creature falls into the pit. The creature can use the Grab an Edge reaction to avoid falling. Failing that, the creature falls 20 feet (taking 10 bludgeoning damage from the fall) and takes 3d6 piercing damage from the metal spikes jutting up from the pit's floor. A creature who takes damage from the spikes is exposed to tetanus.",
          "traits": []
        },
        {
          "id": "eo8fMROlGq0iW5oz",
          "name": "Tetanus",
          "kind": "passive",
          "description": "Saving Throw check (fortitude, dc:14)\nOnset 10 days\nStage 1 Clumsy 1 (1 week)\nStage 2 Clumsy 2 and can't speak (1 day)\nStage 3 Paralyzed with spasms (1 day)\nStage 4 death",
          "traits": [
            "disease"
          ]
        }
      ]
    },
