    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Mindhammer Mushrooms",
      "level": 3,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "environmental",
        "fungus"
      ],
      "description": "The mushrooms emit powerful psychic blasts that overwhelm potential predators with exhausting psychedelic visions.",
      "armorClass": 16,
      "hitPoints": 20,
      "hardness": 0,
      "stealth": {
        "modifier": 10,
        "details": "(trained) to notice small animal skeletons among the mushrooms"
      },
      "disable": "check (survival, dc:20) (trained) to navigate a safe path without triggering the mushrooms",
      "isComplex": false,
      "routine": "",
      "reset": "The mushrooms must rest for 24 hours before they can emit another Psychic Blast.",
      "saves": {
        "fortitude": 10,
        "reflex": 8,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "tRRScI0VDZX7G4mY",
          "name": "Psychic Blast",
          "kind": "reaction",
          "description": "Trigger A creature walks through the mushrooms\nEffect The mushrooms release a loud hum of psychic energy. The triggering creature takes 2d8+8 mental damage (check (will, dc:23, basic)). On a critical failure, the creature is Fatigued.",
          "traits": []
        }
      ]
    },
