    "sourceHash": "sha256:a4babfced91bc690a1244a8e71bacf13bab62e7904319bf1e9590c72208d535f",
    "translatableHash": "sha256:53cb4e6224b87366bd1151a6a9a954196ddb7e43d192e0fb801532a6bb1941ff",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Formian Sting Trench",
      "level": 4,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "mechanical",
        "trap"
      ],
      "description": "A thin layer of canvas conceals this 10-foot-square pit, the walls of which are studded with dagger-sized formian stingers. Creatures that fall into the trap risk being gouged by the poisonous barbs.",
      "armorClass": 18,
      "hitPoints": 30,
      "hardness": 0,
      "stealth": {
        "modifier": 0,
        "details": "(trained)"
      },
      "disable": "check (thievery, dc:22) (trained)",
      "isComplex": false,
      "routine": "",
      "reset": "Creatures can still fall into the trap, but the canvas must be reset manually for the trap to become hidden again.",
      "saves": {
        "fortitude": 8,
        "reflex": 8,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "5dSulgsUGNtmdlLZ",
          "name": "Entrench",
          "kind": "reaction",
          "description": "Trigger A creature walks onto the canvas\nEffect The creature falls into the Concealed trench and takes falling damage (typically 10 bludgeoning damage). The creature is also gouged by three poisoned stingers as they fall. The creature can use the Grab an Edge reaction to avoid falling.",
          "traits": [
            "attack"
          ]
        },
        {
          "id": "uQvenUJQhzfSiqp2",
          "name": "Formian Trench Poison",
          "kind": "passive",
          "description": "Saving Throw check (fortitude, dc:21)\nMaximum Duration 6 rounds\nStage 1 1d6 poison damage (1 round)\nStage 2 1d6 poison damage and Clumsy 1 (1 round)\nStage 3 1d6 poison damage, clumsy 1, and Enfeebled 1 (1 round)\nStage 4 2d6 poison damage, clumsy 1, and enfeebled 1 (1 round)",
          "traits": [
            "poison"
          ]
        }
      ]
    },
