    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Valmar's Pit Trap",
      "level": 4,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "mechanical",
        "trap"
      ],
      "description": "The ground here is made of loosely packed soil that, when stepped upon, collapses.",
      "armorClass": 10,
      "hitPoints": 6,
      "hardness": 1,
      "stealth": {
        "modifier": 15,
        "details": "(expert)"
      },
      "disable": "check (survival, dc:22) (trained) to reinforce the dirt so it's safe to walk on, or check (thievery, dc:18) (trained) to collapse the trap from a safe distance",
      "isComplex": false,
      "routine": "",
      "reset": "Creatures can still fall into the pit, but the soil must be replaced for the trap to become hidden again.",
      "saves": {
        "fortitude": 2,
        "reflex": 3,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "dnIx3U20Cjg7YLMD",
          "name": "Collapse",
          "kind": "reaction",
          "description": "Trigger A creature steps onto any space in the dotted area on the map, or at least 30 pounds of pressure is put on the area\nEffect The ground gives way. The triggering creature falls 20 feet down the hole, taking 10 bludgeoning damage and landing Prone in area E10. A creature can Grab an Edge to avoid falling.",
          "traits": []
        }
      ]
    },
