    "translatableHash": "sha256:87e082b6b11bab748f47fdb8b5ef350c8d621f11ec624f4321c8cdb61ab631cd",
    "data": {
      "schemaVersion": 1,
      "name": "Myroga",
      "level": 6,
      "rarity": "rare",
      "size": "large",
      "traits": [
        "dragon"
      ],
      "description": "Myrogas are avaricious, simple-minded dragons with supernatural occult powers. They draw their amazing abilities from ley lines—loci of intense magical energy often associated with psychic phenomena.\nA myroga encountered away from a ley line is far less dangerous, a fact which myrogas recognize and take great pains to mitigate. Upon discovering an unoccupied ley line, a myroga is apt to roost nearby and guard the site ferociously. All the while, it sups on the ley line's nearly inexhaustible ambient magic to grow stronger and expand its repertoire of brutal powers.",
      "armorClass": 24,
      "hitPoints": 120,
      "speedFeet": 20,
      "perception": {
        "modifier": 17,
        "senses": [
          "darkvision",
          "scent-imprecise-30"
        ]
      },
      "saves": {
        "fortitude": 16,
        "reflex": 15,
        "will": 14
      },
      "abilities": {
        "str": 4,
        "dex": 3,
        "con": 4,
        "int": 2,
        "wis": 2,
        "cha": 5
      },
      "skills": {
        "acrobatics": 15,
        "athletics": 14,
        "intimidation": 15,
        "occultism": 14
      },
      "languages": [
        "aklo",
        "draconic"
      ],
      "defenses": {
        "immunities": [
          "paralyzed",
          "sleep"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "XjtcKSM84578lH0F",
          "name": "Fangs",
          "bonus": 16,
          "damage": "2d8+7 piercing",
          "traits": [
            "reach-10"
          ]
        },
        {
          "id": "s3BSfDdveoMXp9sG",
          "name": "Tail",
          "bonus": 16,
          "damage": "2d6+7 bludgeoning",
          "traits": [
            "reach-15"
          ]
        },
        {
          "id": "EvwUEh34Z3d0syNb",
          "name": "Talon",
          "bonus": 16,
          "damage": "2d6+7 slashing",
          "traits": [
            "agile",
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "UFPn3eDD3FtZjWL5",
          "name": "Ley Line Sense (Imprecise)",
          "kind": "passive",
          "description": "The myroga can sense the presence, direction, and strength of any ley line within 1 mile.",
          "traits": []
        },
        {
          "id": "rvkUENe3nzhqFAYf",
          "name": "Reactive Strike (Fangs Only)",
          "kind": "reaction",
          "description": "",
          "traits": []
        },
        {
          "id": "4EXIYyu6eMaG2vp9",
          "name": "Resistance 5 to Physical Near a Ley Line",
          "kind": "passive",
          "description": "The myroga has resistance to physical 5 while within 500 feet of a ley line.",
          "traits": []
        },
        {
          "id": "DoxF5itUrulTxQNS",
          "name": "Draconic Frenzy",
          "kind": "action",
          "description": "The myroga makes two talon Strikes and one tail Strike in any order.",
          "traits": []
        },
        {
          "id": "HOs28U58lkST9C2Z",
          "name": "Ley Line Empowerment",
          "kind": "action",
          "description": "Requirements The myroga is within 500 feet of a ley line\nEffect The myroga wreathes itself in raw destructive energy converted from the ley line's ambient magic. The myroga deals an additional 2d6 force damage with each of its next successful fangs, tail, and talon Strike. Once its dealt damage with one of these Strikes, the energy is discharged from that body part, but not the others.",
          "traits": [
            "force",
            "occult"
          ]
        },
        {
          "id": "mtj8UTiVC6QPDtgV",
          "name": "Ley Line Rupture",
          "kind": "action",
          "description": "Requirements The myroga is within 500 feet of a ley line\nEffect The myroga diverts some of the ley line's magic into a deadly and distant explosion. The myroga creates a detonation of force in a 5-foot square within a mile of its ley line and that it can see, dealing 5d6 force damage to creatures (check (reflex, dc:24, basic)). A myroga can will the detonation into existence anywhere within a mile of the ley line, possibly allowing it to ignore cover the target might have from, for example, an obstacle between itself and the myroga.",
          "traits": [
            "attack",
            "force",
            "occult"
          ]
        }
      ],
      "spellcasting": [
        {
          "id": "a6ral8pUDUSQzASx",
          "name": "Occult Innate Spells",
          "tradition": "occult",
          "category": "innate",
          "attackModifier": 15,
          "saveDc": 23,
          "spells": [
            {
              "id": "rSwXe6XBRaNJa0eh",
              "name": "Grim Tendrils",
              "rank": 3
            }
          ]
        }
      ]
    },
