    "data": {
      "schemaVersion": 1,
      "name": "The Guest",
      "level": 7,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "aberration",
        "humanoid"
      ],
      "description": "",
      "armorClass": 24,
      "hitPoints": 130,
      "speedFeet": 25,
      "perception": {
        "modifier": 15,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 17,
        "reflex": 14,
        "will": 13
      },
      "abilities": {
        "str": 4,
        "dex": 3,
        "con": 4,
        "int": -4,
        "wis": 2,
        "cha": 0
      },
      "skills": {
        "acrobatics": 14,
        "athletics": 17
      },
      "languages": [],
      "defenses": {
        "immunities": [],
        "resistances": [
          "bludgeoning 10",
          "cold 10"
        ],
        "weaknesses": [
          "slashing 10"
        ]
      },
      "attacks": [
        {
          "id": "sJGD4KrnEDUPhooi",
          "name": "Claw",
          "bonus": 17,
          "damage": "2d6 + 10 slashing; 1d6 cold",
          "traits": [
            "unarmed",
            "versatile-b"
          ]
        }
      ],
      "actions": [
        {
          "id": "mUdgb2Cqijvvw65Y",
          "name": "Fall Apart",
          "kind": "passive",
          "description": "When one of the Guests dies, its body falls apart into a tangle of meat, gristle, fur, bone, and gore. All creatures within a 10-foot emanation (other than other Guests) must make a check (will, dc:22) save to avoid becoming Sickened 2 (Sickened 4 on a critical failure) at the sight and smell of this fate.",
          "traits": [
            "occult"
          ]
        },
        {
          "id": "YFKxEov4UIVw4Pto",
          "name": "Frozen Wind",
          "kind": "action",
          "description": "The guest exhales a blast of freezing wind from its body in a 20-foot cone. All creatures in this area take 8d6 cold damage (check (reflex, dc:25, basic, options:area-effect)). The Guest can't use Frozen Wind again for 1d4.",
          "traits": []
        },
        {
          "id": "hDpm7a2OXARGsF4P",
          "name": "Stunning Critical",
          "kind": "passive",
          "description": "If a Guest critically hits a creature with a claw Strike, the target must make a check (fortitude, dc:25) save or be Stunned 1.",
          "traits": []
        },
        {
          "id": "q1j5oT9xOrRhtlbn",
          "name": "Trigger Memory",
          "kind": "passive",
          "description": "Trigger A gatewalker attempts to Strike a Guest or target a Guest with a spell\nEffect The first time a gatewalker (including any PC) attempts to Strike a Guest or target it with a spell, a repressed memory from their Missing Moment surfaces. For a brief instant, the character recalls facing down a much larger and fully formed saumen kar, one with four horns and glowing runes on its fur. This memory of the character's first encounter with Ainamuuren evokes waves of fear and shame. The character must make a successful check (will, dc:25) save or become Frightened 1 (Frightened 2 on a critical failure), after which the character is immune to Trigger Memory.",
          "traits": [
            "emotion",
            "fear",
            "mental",
            "occult"
          ]
        }
      ],
      "spellcasting": []
    },
