    "sourceHash": "sha256:70ca220da1990b86e5398551b81ec228d34cb783ac9c88ef6ea74666940c5c14",
    "translatableHash": "sha256:443e059bbec4322265ccfc6ecbd56c8d9fad98317c8a3b6a56753f870fe957e6",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Soporific Lecture",
      "level": 8,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "mechanical",
        "trap"
      ],
      "description": "Several hidden nozzles spray colorless sleeping gas into the seating area.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 18,
        "details": "(expert)"
      },
      "disable": "check (thievery, dc:28) (expert) to crimp shut the primary feeding tube for the gas, or check (perception, dc:31) (expert) to discover the hidden bypass switch next to the door to area A3 that shuts the trap off",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "ECUSd3QDyKQ2qHVB",
          "name": "Gas Spray",
          "kind": "reaction",
          "description": "Trigger Pressure is applied to any of the steps in the middle of the seating area, or applied to the manual trigger on the stage. This manual trigger can activate the trap even if its Hidden bypass switch is engaged\nEffect Sleeping gas is silently sprayed into the seating area. All creatures in the area must roll a check (will, dc:26) save to resist its effects. The gas persists in the area for 3 rounds before becoming inert. Any creature who ends their turn in this area during these 3 rounds must attempt a new check (will, dc:26) save.\nCritical Success The creature is unaffected and realizes that the area has been gassed.\nSuccess The creature is unaffected but doesn't notice the gas.\nFailure The creature feels a bit drowsy and lethargic, and becomes Fatigued for 1 minute. If the creature is already fatigued, it instead falls Unconscious. If it's still unconscious after 1 minute, it wakes up automatically.\nCritical Failure The creature falls unconscious. If it's still unconscious after 1 hour, it wakes up automatically.",
          "traits": [
            "incapacitation",
            "mental",
            "poison",
            "sleep"
          ]
        }
      ]
    },
