    "translatableHash": "sha256:57217beea02045b212781cce907234aea1184775dbaa8b86b8282d8ce0cc7325",
    "data": {
      "schemaVersion": 1,
      "name": "Warty",
      "level": 2,
      "rarity": "unique",
      "size": "large",
      "traits": [
        "animal"
      ],
      "description": "Most giant toads live in dry environments, particularly deserts, and eagerly eat almost any creature smaller than themselves. They're known to eat giant rats, then take over the rats' burrows as homes. Giant toads have large poison glands behind their eyes that enable them to coat their skin with poison. This leads to them having very few natural predators, and populations can quickly explode if left unchecked. While most consider giant toads dangerous pests, some groups of ogres and hill giants cultivate them to collect their poison for recreational use.",
      "armorClass": 17,
      "hitPoints": 36,
      "speedFeet": 25,
      "perception": {
        "modifier": 8,
        "senses": [
          "low-light-vision",
          "scent-imprecise-30"
        ]
      },
      "saves": {
        "fortitude": 9,
        "reflex": 8,
        "will": 6
      },
      "abilities": {
        "str": 5,
        "dex": 2,
        "con": 3,
        "int": -4,
        "wis": 2,
        "cha": -2
      },
      "skills": {
        "athletics": 9,
        "stealth": 6
      },
      "languages": [],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "Nz9xljPpg09kcxBl",
          "name": "Jaws",
          "bonus": 11,
          "damage": "1d8+5 piercing",
          "traits": []
        },
        {
          "id": "jOuIuz89du1DGTFh",
          "name": "Tongue",
          "bonus": 11,
          "damage": "",
          "traits": [
            "reach-10"
          ]
        }
      ],
      "actions": [
        {
          "id": "AhfsEZ9fBUS6e02P",
          "name": "Poisonous Warts",
          "kind": "passive",
          "description": "Any creature that hits the Warty with an unarmed Strike or otherwise touches the toad is exposed to giant toad poison.",
          "traits": []
        },
        {
          "id": "KQBI90QlI48BEPP3",
          "name": "Giant Toad Poison",
          "kind": "passive",
          "description": "Saving Throw check (fortitude, dc:19)\nMaximum Duration 6 rounds\nStage 1 Stupefied 1 (1 round)\nStage 2 Stupefied 1 and Confused (1 round)",
          "traits": [
            "poison"
          ]
        },
        {
          "id": "aJC4bsCLoFw8v0QS",
          "name": "Slurp Something Shiny",
          "kind": "action",
          "description": "Warty makes a Disarm attempt with his tongue Strike against a shiny object held by a target in reach.",
          "traits": [
            "attack"
          ]
        },
        {
          "id": "yFWK77O4rMtMcEmp",
          "name": "Swallow Whole",
          "kind": "action",
          "description": "Medium, 1d8 bludgeoning damage, Escape DC 18 Rupture 8",
          "traits": [
            "attack"
          ]
        },
        {
          "id": "tmi63gM84pc6s5qK",
          "name": "Tongue Grab",
          "kind": "passive",
          "description": "A creature hit by Warty's tongue becomes Grabbed by the giant toad. The creature isn't Immobilized, but it can't move beyond the reach of the toad's tongue.\nA creature can sever the tongue with a successful Strike against AC 15 that deals at least 6 slashing damage. This deals no damage to Warty, but prevents him from using his tongue Strike until he regrows his tongue, which takes a week.",
          "traits": []
        },
        {
          "id": "pntbmMiiU6IArfJX",
          "name": "Grab",
          "kind": "action",
          "description": "",
          "traits": []
        }
      ],
      "spellcasting": []
    },
