    "sourceHash": "sha256:7ef01d2ab4a9fba37ea19790f1b6db31a47197aa855d6a538b38f41e6a2cd259",
    "translatableHash": "sha256:52ec818329f059c3af2cbc9c4d511fdc309bef19d3dee1cd0efbebc73d8c7ad7",
    "data": {
      "schemaVersion": 1,
      "name": "Hu Ban-Niang",
      "level": 5,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "human",
        "humanoid",
        "lawful"
      ],
      "description": "",
      "armorClass": 20,
      "hitPoints": 75,
      "speedFeet": 25,
      "perception": {
        "modifier": 11,
        "senses": []
      },
      "saves": {
        "fortitude": 10,
        "reflex": 10,
        "will": 13
      },
      "abilities": {
        "str": 2,
        "dex": 1,
        "con": 1,
        "int": 2,
        "wis": 2,
        "cha": 4
      },
      "skills": {
        "athletics": 11,
        "crafting": 11,
        "deception": 13,
        "diplomacy": 11,
        "intimidation": 13,
        "society": 11
      },
      "languages": [
        "common",
        "halfling"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "jHxGlmXoCHiUGCFv",
          "name": "Longsword",
          "bonus": 13,
          "damage": "2d8+3 slashing",
          "traits": [
            "magical",
            "versatile-p"
          ]
        }
      ],
      "actions": [
        {
          "id": "SINzM5NNW1nMlY2L",
          "name": "So Have You Heard?",
          "kind": "passive",
          "description": "Frequency once per day\nEffect Granny Hu can shift a PC's reputation in Willowshore over the course of 2 hours of work. She attempts a Deception check against the target's check (deception, defense:deception), check (deception, defense:diplomacy), or check (deception, defense:intimidation) DC, whichever is highest. If the target is admired or revered by at least one faction in Willowshore, Granny Hu takes a –1 status penalty to her check, or –2 if the target is admired or revered by both factions. The target is then temporarily immune to So Have You Heard? for 1 week.\nCritical Success The target takes a –2 circumstance penalty to Charisma-based skill checks when interacting with Willowshore residents for a week.\nSuccess As critical success, but only a –1 circumstance penalty and for only 1 day.\nFailure The target is unaffected.\nCritical Failure The plan backfires; not only is the target unaffected, but Granny Hu can't use So Have You Heard? for 1 month.",
          "traits": [
            "exploration"
          ]
        },
        {
          "id": "QEZc2a2zythejido",
          "name": "Are You Sure About That?",
          "kind": "reaction",
          "description": "Trigger A creature within 30 feet who's visible to Granny Hu and who has been exposed to Want to Try Me? in the past week says or does something that would be against Granny Hu's interests\nEffect Granny Hu makes a subtle gesture, reminding the triggering creature of their secret. The creature must succeed at a check (will, dc:22) Save or the triggering action is disrupted. Regardless of the outcome, the creature then becomes temporarily immune to this ability for 24 hours.",
          "traits": [
            "emotion",
            "mental",
            "visual"
          ]
        },
        {
          "id": "petYD8BwpqXAO6am",
          "name": "Nerves of Steel",
          "kind": "passive",
          "description": "If Granny Hu succeeds at a save against a fear effect, she gets a critical success instead.",
          "traits": []
        },
        {
          "id": "LoNKzEELMKd1bQ9C",
          "name": "Want to Try Me?",
          "kind": "reaction",
          "description": "Trigger A creature within 30 feet attempts to Coerce or Demoralize a creature\nEffect Granny Hu threatens to expose a secret of the triggering creature. She attempts an check (intimidation, defense:will) check against the triggering creature's Will DC. Her reputation means she can threaten a PC even if she doesn't actually know a secret, but if she does know an especially dangerous or shameful one, she gains a +2 circumstance bonus to her Intimidation check.\nCritical Success The creature is Frightened 2, and the result of their Coerce or Demoralize attempt is reduced by one degree of success.\nSuccess As success, but Frightened 1.\nFailure The creature is unaffected.\nCritical Failure The creature is unaffected, gains a +1 circumstance bonus to their Coerce or Demoralize attempt, and is immune to Want to Try Me? for 24 hours.",
          "traits": [
            "auditory",
            "emotion",
            "fear",
            "mental"
          ]
        }
      ],
      "spellcasting": []
    },
