    "sourceHash": "sha256:0a2f4acda589ae795ceb40c4f31dc7d93e62ed3800e47d5912875ff377c1b682",
    "translatableHash": "sha256:ef0e80e963340b5428e690547d25f03b84ece765499cbe6e3d1a99f95c4e10b9",
    "data": {
      "schemaVersion": 1,
      "name": "Taunting Monk's Skull",
      "level": 6,
      "rarity": "unique",
      "size": "tiny",
      "traits": [
        "evil",
        "undead",
        "unholy"
      ],
      "description": "Some beheaded are raised with their mental faculties mostly intact. These clever undead often provoke their victims into foolishly giving chase or harming themselves.\nBeheaded are disembodied floating heads transformed into undead. They are natural candidates for a necromancer's \"project minion,\" due to the inexpensive cost of creation and endlessly customizable nature. In any lair occupied for long by practicing necromancers, it isn't uncommon to find a handful of floating heads roaming about, each exhibiting completely different characteristics and even degrees of expertise in their creation.",
      "armorClass": 24,
      "hitPoints": 100,
      "speedFeet": 0,
      "perception": {
        "modifier": 15,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 12,
        "reflex": 16,
        "will": 13
      },
      "abilities": {
        "str": 1,
        "dex": 5,
        "con": 1,
        "int": 0,
        "wis": 4,
        "cha": 1
      },
      "skills": {
        "acrobatics": 14,
        "intimidation": 14
      },
      "languages": [
        "common",
        "necril"
      ],
      "defenses": {
        "immunities": [
          "bleed",
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "unconscious"
        ],
        "resistances": [],
        "weaknesses": [
          "vitality 5"
        ]
      },
      "attacks": [
        {
          "id": "f303t130pkbopzk0",
          "name": "Jaws",
          "bonus": 16,
          "damage": "2d8+5 piercing; 1d6 mental",
          "traits": [
            "agile",
            "finesse",
            "reach-0",
            "unarmed"
          ]
        },
        {
          "id": "J92UF8bItf0RpLEn",
          "name": "Ectoplasmic Spit",
          "bonus": 0,
          "damage": "3d6 spirit",
          "traits": []
        }
      ],
      "actions": [
        {
          "id": "qxv9k072qjlqqrmv",
          "name": "Bite Back",
          "kind": "reaction",
          "description": "Trigger The skull is attacked by a creature within their reach\nEffect The skull makes a jaws Strike against that creature.",
          "traits": []
        },
        {
          "id": "apXBdiwzInrE6nhf",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "8c65aVAQlagz2Ix5",
          "name": "Behold the Promises of Kugaptee!",
          "kind": "action",
          "description": "The skull chooses one creature within 60 feet and speaks to them about the oblivion they'll be granted if they cede their soul to Kugaptee. The target must attempt a check (will, dc:24) save.\nCritical Success The target is unaffected and is temporarily immune for 1 minute.\nSuccess The target is unaffected.\nFailure The target is Off-Guard for 1 round.\nCritical Failure The target is Paralyzed by despair for 1 round, and is then off-guard for 1 additional round.",
          "traits": [
            "auditory",
            "emotion",
            "incapacitation",
            "mental"
          ]
        }
      ],
      "spellcasting": []
    },
