    "data": {
      "schemaVersion": 1,
      "name": "Rin",
      "level": 8,
      "rarity": "unique",
      "size": "small",
      "traits": [
        "chaotic",
        "ghost",
        "incorporeal",
        "kitsune",
        "spirit",
        "undead"
      ],
      "description": "",
      "armorClass": 26,
      "hitPoints": 100,
      "speedFeet": 30,
      "perception": {
        "modifier": 15,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 13,
        "reflex": 19,
        "will": 13
      },
      "abilities": {
        "str": -5,
        "dex": 6,
        "con": 2,
        "int": 0,
        "wis": 3,
        "cha": 6
      },
      "skills": {
        "stealth": 18,
        "survival": 17
      },
      "languages": [
        "common"
      ],
      "defenses": {
        "immunities": [
          "bleed",
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "precision",
          "unconscious"
        ],
        "resistances": [
          "all-damage 10 except force, ghost-touch, spirit, vitality"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "BiciqcQOgzrHVCFN",
          "name": "Burning Touch",
          "bonus": 18,
          "damage": "2d8+12 fire",
          "traits": [
            "agile",
            "finesse"
          ]
        }
      ],
      "actions": [
        {
          "id": "g3j25NGy2OoJ5bxz",
          "name": "Mindscape Bound",
          "kind": "passive",
          "description": "Rin is bound to the Willowshore mindscape and can travel anywhere within its borders.\nA typical ghost can stray only a short distance from where it was killed or the place it haunts. A typical limit is 120 feet. Some ghosts are instead bound to a room, building, item, or creature that was special to it rather than a location.",
          "traits": []
        },
        {
          "id": "8z77rQSz6dMyrvoJ",
          "name": "Rejuvenation",
          "kind": "passive",
          "description": "When a ghost is destroyed, it re-forms after 2d4 within the location it's bound to, fully healed. A ghost can be permanently destroyed only if someone determines the reason for its existence and sets right whatever prevents the spirit from resting.",
          "traits": [
            "divine"
          ]
        },
        {
          "id": "y3USxtluu5GTxPHO",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "Ou3LG2R9dDZPZQIZ",
          "name": "Change Shape",
          "kind": "action",
          "description": "Rin transforms into the tailless form of a specific small human. The tailless form can't be altered and resembles her fox-like humanoid form.",
          "traits": [
            "concentrate",
            "divine",
            "polymorph"
          ]
        },
        {
          "id": "fWSjverMzSyj4vrn",
          "name": "Foxfire Curse",
          "kind": "passive",
          "description": "A creature damaged by Rin's burning touch must succeed at a check (will, dc:25) save or become cursed. During a cursed creature's moments of triumph, they become limned with spectral flames that punish their allies. Whenever the cursed creature scores a critical hit, each ally within their reach takes 1d6 persistent fire damage as the cursed creature's hubris sears them. This curse has an unlimited duration.",
          "traits": [
            "curse",
            "fire",
            "primal"
          ]
        }
      ],
      "spellcasting": []
    },
