      "actions": [
        {
          "id": "soDnnr4uJeQaHJ5Y",
          "name": "Command Onidoshi",
          "kind": "action",
          "description": "Frequency once per round\nEffect Gurglegut barks out a command to a single mountain oni in area D1. That oni can use a reaction to attempt a melee Strike against an adjacent foe.",
          "traits": [
            "auditory",
            "linguistic"
          ]
        },
        {
          "id": "N3pKiPqxLvGzdVJg",
          "name": "Spit Fire",
          "kind": "action",
          "description": "Frequency once per day\nEffect Gurglegut drinks the contents of his jug of rice wine (consuming one of the gulps contained in his jug), then spews it out across the flaming tip of a bolt in his crossbow, filling a 20-foot cone with a blast of fire that inflicts 10d8 fire damage (check (reflex, dc:32, basic, options:area-effect) save) to all creatures in the area.",
          "traits": [
            "fire",
            "manipulate"
          ]
        }
      ],
