    "sourceHash": "sha256:7caf17f2d877f5b6ca8c57524be77a77ce891c83e7e479f7c765d7c6186ca7c7",
    "translatableHash": "sha256:f8005191f52519f3d0e136026e5489d942ca99b5ceb6edf864608be5bbed40b3",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Witherweird Runes",
      "level": 13,
      "rarity": "rare",
      "size": "medium",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "Magic stored in runes painted in powdered bone and banshees' tears lash out at anyone other than Heh Shan-Bao who opens the secondary compartment.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 27,
        "details": "(master)"
      },
      "disable": "Disable Device DC 37 to scratch out the runes and dissipate their magic harmlessly, check (arcana, dc:40) to sabotage the spell and cause the runes to dry up and blow away as inert powder, or Dispel Magic (7th rank; counteract DC 31) to counteract the runes",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "m20J0FChdD0pINqW",
          "name": "Withering Wail",
          "kind": "reaction",
          "description": "Trigger Someone other than Heh Shan-Bao opens the secondary compartment\nEffect A howling, spectral face manifests out of the chest and screeches, causing all within area C4 to attempt a check (fortitude, dc:33) save; the sound also alerts the jiang-shi in areas C3 a and C6, who quickly come to investigate the sound.\nCritical Success The creature is unaffected.\nSuccess The creature takes 7d6 void damage.\nFailure The creature takes 15d6 void damage. In addition, their flesh withers and weakens, leaving them to appear old and decrepit—the creature becomes Clumsy 1 and Enfeebled 1 until the curse is removed.\nCritical Failure The creature takes 30d6 void damage and becomes cursed as failure above, but becomes Clumsy 2 and Enfeebled 2.",
          "traits": [
            "arcane",
            "curse"
          ]
        }
      ]
    },
