      "attacks": [
        {
          "id": "jU79jFJvAIR96szG",
          "name": "Shears",
          "bonus": 11,
          "damage": "1d8+4 slashing",
          "traits": [
            "finesse",
            "forceful",
            "magical"
          ]
        }
      ],
      "actions": [
        {
          "id": "6JjZlgF6ldSwrl3y",
          "name": "Shears",
          "kind": "passive",
          "description": "An azhana carries a pair of gardening shears about 10 inches long. In the hands of an azhana, these shears function as an elven curve blade. If an azhana's shears are lost or destroyed, they can make another pair with a week of work and a few scraps of metal.",
          "traits": []
        },
        {
          "id": "ijG9oUFCuYyRhFuj",
          "name": "Speak with Water",
          "kind": "passive",
          "description": "Once per day, four azhanas within 15 feet of each other can perform a 1-minute rite to communicate with an adjacent body of fresh water at least as large as an azhana. This ability functions like Speak with Stones. Flowing water can generally speak about events happening upstream (even distantly upstream), but not events happening downstream.",
          "traits": [
            "auditory",
            "concentrate",
            "primal"
          ]
        }
      ],
