    "data": {
      "schemaVersion": 1,
      "name": "Besieged Logging Crew",
      "level": 4,
      "rarity": "common",
      "size": "gargantuan",
      "traits": [
        "human",
        "humanoid",
        "troop"
      ],
      "description": "",
      "armorClass": 18,
      "hitPoints": 60,
      "speedFeet": 25,
      "perception": {
        "modifier": 7,
        "senses": []
      },
      "saves": {
        "fortitude": 12,
        "reflex": 9,
        "will": 10
      },
      "abilities": {
        "str": 3,
        "dex": 2,
        "con": 2,
        "int": 1,
        "wis": 2,
        "cha": 1
      },
      "skills": {
        "acrobatics": 9,
        "athletics": 12,
        "nature": 8,
        "survival": 10
      },
      "languages": [
        "common",
        "fey"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": [
          "area-damage 10",
          "splash-damage 5"
        ]
      },
      "attacks": [],
      "actions": [
        {
          "id": "f0GgNYxdBPXudGic",
          "name": "Form Up",
          "kind": "action",
          "description": "",
          "traits": []
        },
        {
          "id": "bbCrE3ZGa2Z9Ak17",
          "name": "Troop Defenses",
          "kind": "passive",
          "description": "Thresholds 40 (3 segments), 20 (2 segments)",
          "traits": []
        },
        {
          "id": "DCAHmNtG0hWB0FHQ",
          "name": "Hurl Axes",
          "kind": "action",
          "description": "The loggers draw their hatchets, then launch a ranged attack in the form of a volley. This volley is a 10-foot burst within 120 feet that deals 3d6 slashing damage (check (reflex, dc:18, basic, options:area-effect) save). When the crew is reduced to 8 or fewer squares, this area decreases to a 5-foot burst.",
          "traits": []
        },
        {
          "id": "YqzdF6r4efrzdR6n",
          "name": "Tandem Chop",
          "kind": "action",
          "description": "1 to 3\nFrequency once per round\nEffect The loggers engage in a coordinated axe attack against each enemy within 10 feet, with a check (reflex, dc:19, basic) save. The damage depends on the number of actions expended.\n1 1d10 slashing damage\n2 3d6+7 slashing damage\n3 3d6+10 slashing damage",
          "traits": []
        },
        {
          "id": "QpSvCYrDNe5et7o6",
          "name": "Troop Movement",
          "kind": "passive",
          "description": "Whenever the loggers Stride, they first Form Up as a free action to condense into a 20-foot-by-20-foot area (minus any missing squares), then move up to their Speed. This works just like a Gargantuan creature moving; for instance, if any square of the logging crew enters difficult terrain, the extra movement cost applies to all the loggers.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
