    "sourceHash": "sha256:a40d766fedc41b8dfd2778bd184706f85c4d53cc8fe043790681fb98de7ee1b3",
    "translatableHash": "sha256:6b011f942dbd3e580554df3f253b5167bbd6bdddde3e347a72fd51510bf134de",
    "data": {
      "schemaVersion": 1,
      "name": "Koata Inuu",
      "level": 7,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "humanoid",
        "strix"
      ],
      "description": "As is reflected in the many depictions of an elk-headed Erastil, god of the hunt, the hunter is very much a creature of the forest, known by the forest and familiar with every aspect of it. After all, the final determination of who is the hunter and who is prey often depends on who is able to make an ally of the terrain.\nFrom the managed and cultivated forests that support villages to the tree-covered crown lands where only nobles and their servants are permitted to hunt, forests provide. To communities, forests provide fuel, food, medicine, and raw materials, while royally protected forests provide food for the nobles' table and a source of entertainment in the form of organized hunts. Even the ancient woods untouched by mortal hand or blade provide bards with settings where legends happened and could happen again. Many find the forest depths unsettling, but others live their lives among the trees and alongside the creatures that make their homes there.",
      "armorClass": 25,
      "hitPoints": 115,
      "speedFeet": 25,
      "perception": {
        "modifier": 17,
        "senses": []
      },
      "saves": {
        "fortitude": 15,
        "reflex": 17,
        "will": 15
      },
      "abilities": {
        "str": 4,
        "dex": 4,
        "con": 2,
        "int": 1,
        "wis": 4,
        "cha": 0
      },
      "skills": {
        "medicine": 15,
        "nature": 17,
        "stealth": 17,
        "survival": 17
      },
      "languages": [
        "common"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "CmXRYDHVFD9zOTaa",
          "name": "Dagger",
          "bonus": 18,
          "damage": "1d4+9 piercing",
          "traits": [
            "agile",
            "finesse",
            "versatile-s"
          ]
        },
        {
          "id": "dYlvFC5F1daX6NF8",
          "name": "Shortsword",
          "bonus": 18,
          "damage": "1d6+9 piercing",
          "traits": [
            "agile",
            "finesse",
            "versatile-s"
          ]
        },
        {
          "id": "kotKhpigThVYS6sL",
          "name": "Talon",
          "bonus": 18,
          "damage": "1d6+9 slashing",
          "traits": [
            "agile",
            "finesse",
            "unarmed"
          ]
        },
        {
          "id": "KbYGZddUNQGhrhEf",
          "name": "Composite Longbow",
          "bonus": 18,
          "damage": "1d8+8 piercing",
          "traits": [
            "deadly-d10",
            "magical",
            "propulsive",
            "reload-0",
            "volley-30"
          ]
        }
      ],
      "actions": [
        {
          "id": "sw2mWVFaQb93J9el",
          "name": "Forager",
          "kind": "passive",
          "description": "While using Survival to Subsist, if the tracker rolls a failure or a critical failure, they get a success instead. If the tracker rolls a success, they can provide food for 16 additional creatures that eat about as much as a human, or 32 creatures on a critical success.",
          "traits": []
        },
        {
          "id": "xeEI4dqDE4PmxOeA",
          "name": "Forest Walker",
          "kind": "passive",
          "description": "The hunter ignores the effects of difficult terrain from a forest environment. They can Sneak through underbrush without the need to attempt a Stealth check as long as the hunter moves no more than 5 feet at a time and is not within 10 feet of an enemy at any point during their movement.",
          "traits": []
        },
        {
          "id": "ImzpAPq1SgMcf7t3",
          "name": "Hunt Prey",
          "kind": "action",
          "description": "The hunter designates a single creature they can see and hear, or one they're Tracking, as their prey. The hunter gains a +2 circumstance bonus to Perception checks to Seek the prey and to Survival checks to Track the prey.\nThe first time the hunter hits the designated prey in a round, they deal an additional 1d8 precision damage. The hunter also ignores the penalty for making ranged attacks within their second range increment.\nThese effects last until the hunter uses Hunt Prey again.",
          "traits": [
            "concentrate"
          ]
        }
      ],
      "spellcasting": []
    },
